#!/usr/bin/env python3
"""Compiled entity loop: ordinary contact boundaries, flags and player ownership."""
from pathlib import Path
import hashlib,json,re,subprocess
r=Path(__file__).resolve().parents[1];o=r/'out/parity-audit/barrier-player-integration';o.mkdir(parents=True,exist_ok=True)
syms={n:int(v,16)&0xffffff for v,n in re.findall(r'^([0-9a-fA-F]+)\s+\w\s+(\w+)\s*$',(r/'out/symbol.txt').read_text(),re.M)}
rh=hashlib.sha256((r/'out/rom.bin').read_bytes()).hexdigest()
s='local cpu=manager.machine.devices[":maincpu"];local m=cpu.spaces.program\nlocal frame=0;local test=-1;local checks=0;local terminal=false\nlocal function clear(a,n)for k=0,n-1 do m:write_u8(a+k,0)end end\nlocal function check(v,why)checks=checks+1;assert(v,why..\' case \'..test)end\nlocal function values()return test%8,(test//8)%2+1,(test//16)%2 end\nlocal function run()\n clear(ENT,48*42);clear(GG,94);clear(FOES,240);clear(WEAPONS,72);clear(IA,96);clear(IW,10);clear(WAVES,106);clear(LARGE,102);clear(KPOOL,64)\n clear(COUNTER,2);clear(MOTION,28);clear(OWN,2);clear(FOOD,202);clear(PICKUP,16);clear(CONVERSION,16);clear(SPAWN,4);clear(CSPAWN,4)\n local clock,players,blocked=values();local owner=clock&1\n m:write_u8(SURVIVAL,0);m:write_u8(GG+84,players);m:write_u8(CLOCK,clock);m:write_u8(PULSE,0);m:write_u8(LIMIT,255);m:write_u8(COLLECTED,0)\n local crush=test//32;local px=crush==1 and 17 or 80;local ox=crush==1 and 18 or 80\n for k=0,1 do local p=GG+k*42;m:write_u16(p,px);m:write_u16(p+2,39);m:write_u8(MOTION+k*14+11,1);m:write_u8(MOTION+k*14+5,2);m:write_u8(MOTION+k*14+6,1)end\n if blocked==1 then m:write_u8(GG+owner*42+34,3)end\n m:write_u16(FOOD,ox);m:write_u8(FOOD+4,3);m:write_u8(FOOD+5,3);m:write_u8(FOOD+6,200);m:write_u8(FOOD+7,8);m:write_u8(FOOD+9,2)\n for x=0xffb000,0xffb03e,2 do m:write_u16(x,0x4e71)end\n m:write_u16(0xffb040,0x4eb9);m:write_u32(0xffb042,FN);m:write_u16(0xffb046,0x60fe)\n cpu.state[\'SR\'].value=0x2700;cpu.state[\'SP\'].value=0xffbfe0;cpu.state[\'PC\'].value=0xffb000\nend\nlocal function finish(err)\n terminal=true;local f=assert(io.open(RESULT,\'w\'));f:write(string.format(\'{"updates":%d,"checks":%d,"error":%s}\',test+1,checks,err and string.format(\'%q\',err)or\'null\'));f:close();manager.machine:exit()\nend\nemu.register_frame_done(function()\n if terminal then return end;frame=frame+1;if frame<60 then return end\n local ok,err=pcall(function()\n if test>=0 then\n  check(cpu.state[\'CURPC\'].value&0xffffff==0xffb046,\'return\')\n  local clock,players,blocked=values();local owner=clock&1;local hit=owner<players and blocked==0\n  local crush=test//32;local px=crush==1 and 17 or 80\n  for k=0,1 do local selected=hit and owner==k\n   check(m:read_u16(GG+k*42)==(selected and (crush==1 and 6 or 92)or px),\'push owner\')\n   check(m:read_u8(GG+k*42+38)==(selected and crush==1 and 1 or 0),\'crush request\')\n   check(m:read_u8(MOTION+k*14+5)==(selected and crush==1 and 0 or 2),\'motion state\')\n   check(m:read_u8(MOTION+k*14+6)==(selected and crush==1 and 0 or 1),\'motion phase\')\n  end\n\n end\n if test==63 then finish();return end;test=test+1;run()\n end)\n if not ok then finish(err)end\nend)\n'
for k,v in {'ENT':syms['g_entities'],'GG':syms['g_game'],'FOES':syms['arcade_foes'],'WEAPONS':syms['arcade_weapons'],'IA':syms['arcade_i_actors'],'IW':syms['arcade_i_wave'],'WAVES':syms['arcade_waves'],'ILIVE':syms['arcade_i_live'],'IRES':syms['arcade_i_reservation'],'CLOCK':syms['wave_clock'],'SURVIVAL':syms['g_survivalRun'],'DIFFICULTY':syms['g_arcadeCombatDifficulty'],'COUNTER':syms['counter'],'MOTION':syms['player_motion'],'OWN':syms['life_owned'],'FOOD':syms['pool'],'PICKUP':syms['arcade_food_pickup'],'CONVERSION':syms['arcade_food_conversion'],'SPAWN':syms['arcade_food_spawn'],'CSPAWN':syms['arcade_food_conversion_spawn'],'PULSE':syms['arcade_food_conversion_pulse'],'LIMIT':syms['arcade_bonus_limit'],'COLLECTED':syms['collected'],'LARGE':syms['arcade_large_actors'],'KPOOL':syms['arcade_k_actors'],'FN':syms['entity_update_all'],'RESULT':json.dumps(str(o/'results.json'))}.items():s=re.sub(r'\b'+k+r'\b',str(v),s)
(o/'run.lua').write_text(s)
subprocess.run(['mame','genesis','-cart',str(r/'out/rom.bin'),'-window','-nomaximize','-resolution','512x448','-video','none','-keyboardprovider','none','-mouseprovider','none','-joystickprovider','none','-noreadconfig','-sound','none','-nothrottle','-skip_gameinfo','-autoboot_script',str(o/'run.lua'),'-cfg_directory',str(o/'cfg'),'-nvram_directory',str(o/'nvram')],cwd=r,stdout=(o/'mame.log').open('w'),stderr=subprocess.STDOUT,timeout=120,check=True)
assert hashlib.sha256((r/'out/rom.bin').read_bytes()).hexdigest()==rh
result=json.loads((o/'results.json').read_text());result['rom_sha256']=rh;(o/'results.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2));assert result['error']is None and result['updates']==64,result
